DROP TABLE IF EXISTS `gt_npc_total_hp`;
CREATE TABLE `gt_npc_total_hp` (
  `Level` TINYINT UNSIGNED NOT NULL,
  `Warrior` FLOAT NOT NULL,
  `Paladin` FLOAT NOT NULL,
  `Hunter` FLOAT NOT NULL,
  `Rogue` FLOAT NOT NULL,
  `Priest` FLOAT NOT NULL,
  `DeathKnight` FLOAT NOT NULL,
  `Shaman` FLOAT NOT NULL,
  `Mage` FLOAT NOT NULL,
  `Warlock` FLOAT NOT NULL,
  `Monk` FLOAT NOT NULL,
  `Druid` FLOAT NOT NULL,
  PRIMARY KEY (`Level`)
) ENGINE=INNODB CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

