    `Id` INT UNSIGNED NOT NULL,
    `Difficulty0` INT UNSIGNED NOT NULL DEFAULT 0,
    `Difficulty1` INT UNSIGNED NOT NULL DEFAULT 0,
    `Difficulty2` INT UNSIGNED NOT NULL DEFAULT 0,
    `Difficulty3` INT UNSIGNED NOT NULL DEFAULT 0,
