    `Difficulty6` INT UNSIGNED NOT NULL DEFAULT 0,
    `Difficulty7` INT UNSIGNED NOT NULL DEFAULT 0,
    `Difficulty8` INT UNSIGNED NOT NULL DEFAULT 0,
    `Difficulty9` INT UNSIGNED NOT NULL DEFAULT 0,
    PRIMARY KEY (`Id`)
) ENGINE=INNODB;

